const key='econ2103-midterm-v1';
function load(){try{return JSON.parse(localStorage.getItem(key)||'{}')}catch{return {}}}
function save(value){try{localStorage.setItem(key,JSON.stringify(value))}catch{}}
document.querySelectorAll('.question').forEach(q=>{q.querySelectorAll('input').forEach(input=>input.addEventListener('change',()=>{const chosen=Number(input.value),answer=Number(q.dataset.answer),good=chosen===answer;const box=q.querySelector('.feedback');box.hidden=false;box.className='feedback '+(good?'good':'bad');box.textContent=(good?'正確 Correct. ':'再試一次 Review. ')+q.dataset.explanation;const data=load();data[q.dataset.key]={correct:good,time:Date.now()};save(data)}))});
const count=document.querySelector('[data-progress]');if(count){let done=Object.keys(load()).length;count.textContent=done+' / 20 questions attempted · 只儲存在此瀏覽器';}
document.querySelectorAll('[data-shift]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-shift]').forEach(x=>x.setAttribute('aria-pressed','false'));b.setAttribute('aria-pressed','true');const line=document.querySelector('#demand-line'),point=document.querySelector('#equilibrium-point'),caption=document.querySelector('#shift-caption');const shift=b.dataset.shift==='up';line.setAttribute('d',shift?'M100 35 L320 255':'M45 35 L265 255');point.setAttribute('cx',shift?'182.5':'155');point.setAttribute('cy',shift?'117.5':'145');caption.textContent=shift?'需求增加：D 右移，均衡價格和數量都上升。Demand shifts right: both P and Q rise.':'原始均衡：需求與供給相交。Initial equilibrium is where demand meets supply.'}));
